#include <memory>
#include <iostream>

class Resource {};

void external_deleter(Resource* r) {
    std::cout << "Manual cleanup." << std::endl;
    delete r;
}

int main() {
    std::auto_ptr<Resource> ap(new Resource());

    // ap owns the resource.
    Resource* raw_ptr = ap.release();

    // ap now owns nothing (is null).
    if (!ap.get()) {
        std::cout << "auto_ptr relinquished ownership." << std::endl;
    }

    // Manual deletion is required.
    external_deleter(raw_ptr);
}
